 district text,name text,address_line text,category text,phone text,tax_code text,
 source_key text,source_url text,verification_note text)),
 ins AS (
 INSERT INTO public.field_prospects(id,area_visit_id,owner_sub,name,address_line,province,district,category,
 phone,tax_code,note,status,source_kind,research_source_key,research_source_url,research_batch)
 SELECT (substr(s.dg,1,8)||'-'||substr(s.dg,9,4)||'-5'||substr(s.dg,14,3)||'-8'||substr(s.dg,18,3)||'-'||substr(s.dg,21,12))::uuid,
 NULL,'ef943de4-18f7-49ef-8340-eefb18855534',s.name,s.address_line,'An Giang',s.district,s.category,s.phone,s.tax_code,
 'Nguồn công khai 21/11/2026; CHƯA GHÉ; GPS chưa xác minh; hoạt động bán lẻ chưa xác minh. '||s.verification_note||' Nguồn: '||s.source_url,
 'new','manual',s.source_key,s.source_url,'2026-11-21-an-giang-old-wave-01'
 FROM src s WHERE s.district IN ('Thành phố Long Xuyên','Thành phố Châu Đốc','Thị xã Tân Châu','Huyện An Phú')
 AND s.source_url LIKE 'https://%'
 AND NOT EXISTS(SELECT 1 FROM public.customers c WHERE c.province='An Giang' AND c.district=s.district
 AND (lower(trim(c.name))=lower(trim(s.name)) OR (c.phone IS NOT NULL AND s.phone IS NOT NULL AND c.phone=s.phone)))
 AND NOT EXISTS(SELECT 1 FROM public.field_prospects p WHERE p.province='An Giang' AND p.district=s.district
 AND (p.research_source_key=s.source_key OR (lower(trim(p.name))=lower(trim(s.name)) AND lower(trim(p.address_line))=lower(trim(s.address_line)))
 OR (p.phone IS NOT NULL AND s.phone IS NOT NULL AND p.phone=s.phone) OR (p.tax_code IS NOT NULL AND s.tax_code IS NOT NULL AND p.tax_code=s.tax_code)))
 ON CONFLICT(research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING RETURNING district,category,phone)
 SELECT district,count(*)::int inserted,count(*) FILTER(WHERE category='nha_sach')::int bookstores,count(*) FILTER(WHERE phone IS NOT NULL)::int phones FROM ins GROUP BY district ORDER BY district;